const sin = (deg) => Math.sin(deg * RAD);
const cos = (deg) => Math.cos(deg * RAD);
const tan = (deg) => Math.tan(deg * RAD);
const clamp = (value, low, high) => Math.min(Math.max(value, low), high);
const asin = (value) => Math.asin(clamp(value, -1, 1)) / RAD;
const acos = (value) => Math.acos(clamp(value, -1, 1)) / RAD;
const atan2 = (y, x) => Math.atan2(y, x) / RAD;
const wrap = (deg) => ((deg % 360) + 360) % 360;
const signed = (deg) => wrap(deg + 180) - 180;
const finite = (value) => value !== null && value !== undefined && value !== "" && Number.isFinite(Number(value));
const keysLabel = (hotkey) => String(hotkey).split("+").map((part) => part.trim()).map((part) => part.charAt(0).toUpperCase() + part.slice(1)).join("+");

export function julian(ms) {
  return ms / DAY_MS + 2440587.5;
}

function centuries(ms) {
  return (julian(ms) - J2000) / 36525;
}

export function sidereal(ms) {
  const days = julian(ms) - J2000;
  const t = days / 36525;
  return wrap(280.46061837 + 360.98564736629 * days + 0.000387933 * t * t - (t * t * t) / 38710000);
}

function obliquity(t) {
  const omega = 125.04 - 1934.136 * t;
  return 23 + (26 + (21.448 - t * (46.815 + t * (0.00059 - t * 0.001813))) / 60) / 60 + 0.00256 * cos(omega);
}

function equatorial(lambda, beta, eps) {
  return {
    ra: wrap(atan2(sin(lambda) * cos(eps) - tan(beta) * sin(eps), cos(lambda))),
    dec: asin(sin(beta) * cos(eps) + cos(beta) * sin(eps) * sin(lambda)),
  };
}

export function horizontal(ha, dec, lat) {
  return {
    alt: asin(sin(lat) * sin(dec) + cos(lat) * cos(dec) * cos(ha)),
    az: wrap(atan2(sin(ha), cos(ha) * sin(lat) - tan(dec) * cos(lat)) + 180),
  };
}

export function sun(ms, lat, lon) {
  const t = centuries(ms);
  const l0 = wrap(280.46646 + t * (36000.76983 + t * 0.0003032));
  const m = 357.52911 + t * (35999.05029 - 0.0001537 * t);
  const e = 0.016708634 - t * (0.000042037 + 0.0000001267 * t);
  const center = sin(m) * (1.914602 - t * (0.004817 + 0.000014 * t)) + sin(2 * m) * (0.019993 - 0.000101 * t) + sin(3 * m) * 0.000289;
  const lambda = wrap(l0 + center - 0.00569 - 0.00478 * sin(125.04 - 1934.136 * t));
  const eps = obliquity(t);
  const place = equatorial(lambda, 0, eps);
  const y = tan(eps / 2) ** 2;
  const eot = (4 * (y * sin(2 * l0) - 2 * e * sin(m) + 4 * e * y * sin(m) * cos(2 * l0) - 0.5 * y * y * sin(4 * l0) - 1.25 * e * e * sin(2 * m))) / RAD;
  const distance = (1.000001018 * (1 - e * e)) / (1 + e * cos(m + center));
  const minutes = (((ms % DAY_MS) + DAY_MS) % DAY_MS) / 60000;
  const ha = (minutes + eot + 4 * lon) / 4 - 180;
  return {...place, lambda, eot, distance, ha, ...horizontal(ha, place.dec, lat)};
}

export function moon(ms, lat, lon) {
  const t = centuries(ms);
  const anomaly = 134.9 + 477198.85 * t;
  const lambda = wrap(218.32 + 481267.881 * t + 6.29 * sin(anomaly) - 1.27 * sin(259.2 - 413335.38 * t) + 0.66 * sin(235.7 + 890534.23 * t)
    + 0.21 * sin(269.9 + 954397.7 * t) - 0.19 * sin(357.5 + 35999.05 * t) - 0.11 * sin(186.6 + 966404.05 * t));
  const beta = 5.13 * sin(93.3 + 483202.03 * t) + 0.28 * sin(228.2 + 960400.87 * t) - 0.28 * sin(318.3 + 6003.18 * t) - 0.17 * sin(217.6 - 407332.2 * t);
  const parallax = 0.9508 + 0.0518 * cos(anomaly) + 0.0095 * cos(259.2 - 413335.38 * t) + 0.0078 * cos(235.7 + 890534.23 * t) + 0.0028 * cos(269.9 + 954397.7 * t);
  const place = equatorial(lambda, beta, obliquity(t));
  const distance = EARTH / sin(parallax);
  const ha = sidereal(ms) + lon - place.ra;
  const seen = horizontal(ha, place.dec, lat);
  const light = sun(ms, lat, lon);
  const dra = light.ra - place.ra;
  const elongation = acos(sin(light.dec) * sin(place.dec) + cos(light.dec) * cos(place.dec) * cos(dra));
  const phase = atan2(light.distance * AU * sin(elongation), distance - light.distance * AU * cos(elongation));
  const limb = wrap(atan2(cos(light.dec) * sin(dra), sin(light.dec) * cos(place.dec) - cos(light.dec) * sin(place.dec) * cos(dra)));
  const parallactic = atan2(sin(ha), tan(lat) * cos(place.dec) - sin(place.dec) * cos(ha));
  return {
    ...place, lambda, beta, distance, phase, limb,
    alt: seen.alt - parallax * cos(seen.alt),
    az: seen.az,
    lit: (1 + cos(phase)) / 2,
    tilt: wrap(limb - parallactic),
    waxing: wrap(lambda - light.lambda) < 180,
  };
}

export function star(entry, ms, lat, lon) {
  const [ra, dec, mag] = entry;
  return {...horizontal(sidereal(ms) + lon - ra, dec, lat), mag};
}

export function subsolar(ms) {
  const light = sun(ms, 0, 0);
  return {latitude: light.dec, longitude: signed(light.ra - sidereal(ms))};
}

export function hex(text) {
  return [1, 3, 5].map((index) => parseInt(text.slice(index, index + 2), 16));
}

export function mix(from, to, share) {
  return from.map((value, index) => value + (to[index] - value) * share);
}

export function css(rgb) {
  return `rgb(${rgb.map((value) => Math.round(value)).join(" ")})`;
}

export function luminance(rgb) {
  const [r, g, b] = rgb.map((value) => {
    const channel = Math.round(value) / 255;
    return channel <= 0.04045 ? channel / 12.92 : ((channel + 0.055) / 1.055) ** 2.4;
  });
  return 0.2126 * r + 0.7152 * g + 0.0722 * b;
}

export function contrast(first, second) {
  const [high, low] = [luminance(first), luminance(second)].sort((a, b) => b - a);
  return (high + 0.05) / (low + 0.05);
}

export function skyAt(alt) {
  const level = clamp(alt, SKY[0][0], SKY[SKY.length - 1][0]);
  const index = Math.max(SKY.findIndex(([edge]) => edge >= level), 1);
  const [low, lowTop, lowBottom] = SKY[index - 1];
  const [high, highTop, highBottom] = SKY[index];
  const share = (level - low) / (high - low);
  return {top: mix(hex(lowTop), hex(highTop), share), bottom: mix(hex(lowBottom), hex(highBottom), share)};
}

export function stage(alt) {
  return STAGES.find(([edge]) => alt < edge)[1];
}

export function starlight(alt) {
  return clamp((-alt - 6) / 10, 0, 1);
}

export function textFor(top, bottom) {
  const both = (text) => Math.min(contrast(text, top), contrast(text, bottom));
  const light = both(BLACK) >= 4.5 || (both(WHITE) < 4.5 && contrast(BLACK, top) >= contrast(WHITE, top));
  const text = light ? BLACK : WHITE;
  return {text, scheme: light ? "light" : "dark", legible: both(text) >= 4.5 ? "all" : "top"};
}

export function tones(ms, latitude, longitude) {
  const light = sun(ms, latitude, longitude);
  const {top, bottom} = skyAt(light.alt);
  return {top, bottom, ...textFor(top, bottom), stage: stage(light.alt), altitude: light.alt};
}

export function zonePlace(zone, fallback) {
  if (Object.hasOwn(DATA.zones, zone)) {
    const spot = DATA.zones[zone];
    return {latitude: spot[0], longitude: spot[1], source: "timezone"};
  }
  if (fallback && finite(fallback.latitude) && finite(fallback.longitude)) {
    return {latitude: Number(fallback.latitude), longitude: Number(fallback.longitude), source: "default"};
  }
  return {latitude: 0, longitude: 0, source: "none"};
}

export function home(config) {
  if (finite(config.latitude) && finite(config.longitude)) {
    return {latitude: Number(config.latitude), longitude: Number(config.longitude)};
  }
  const zoned = zonePlace(config.zone, null);
  return zoned.source === "timezone" ? {latitude: zoned.latitude, longitude: zoned.longitude} : null;
}

export function pose(alpha, beta, gamma, heading) {
  const a = Number.isFinite(heading) ? 360 - heading : alpha;
  const east = -cos(a) * sin(gamma) - sin(a) * sin(beta) * cos(gamma);
  const north = -sin(a) * sin(gamma) + cos(a) * sin(beta) * cos(gamma);
  const up = -cos(beta) * cos(gamma);
  return {azimuth: wrap(atan2(east, north)), altitude: asin(up)};
}

export function parseHotkey(text) {
  const parts = String(text || HOTKEY).toLowerCase().split("+").map((part) => part.trim()).filter(Boolean);
  const key = parts.pop() || "c";
  return {key, alt: parts.includes("alt"), shift: parts.includes("shift"), ctrl: parts.includes("ctrl"), meta: parts.includes("meta")};
}

export function pressed(hotkey, event) {
  const code = event.code || "";
  const key = code.startsWith("Key") ? code.slice(3).toLowerCase() : code.startsWith("Digit") ? code.slice(5) : String(event.key || "").toLowerCase();
  return key === hotkey.key && event.altKey === hotkey.alt && event.shiftKey === hotkey.shift && event.ctrlKey === hotkey.ctrl && event.metaKey === hotkey.meta;
}

export function typing(target) {
  return Boolean(target && (target.isContentEditable || ["INPUT", "TEXTAREA", "SELECT"].includes(target.tagName)));
}

export function readPrefs(cookie) {
  const raw = String(cookie || "").split(/;\s*/).find((part) => part.startsWith(`${COOKIE}=`));
  const params = new URLSearchParams(raw ? raw.slice(COOKIE.length + 1) : "");
  const prefs = {};
  if (MODES.includes(params.get("mode"))) {
    prefs.mode = params.get("mode");
  }
  if (SWITCHES.includes(params.get("orientation"))) {
    prefs.orientation = params.get("orientation");
  }
  return prefs;
}

export function prefsCookie(prefs, domain, secure) {
  const params = new URLSearchParams();
  if (MODES.includes(prefs.mode)) {
    params.set("mode", prefs.mode);
  }
  if (SWITCHES.includes(prefs.orientation)) {
    params.set("orientation", prefs.orientation);
  }
  return [`${COOKIE}=${params}`, "Path=/", "Max-Age=31536000", "SameSite=Lax", ...(domain ? [`Domain=${domain}`] : []), ...(secure ? ["Secure"] : [])].join("; ");
}

let landBits = null;

export function landAt(latitude, longitude) {
  landBits ??= Uint8Array.from(atob(DATA.land), (char) => char.charCodeAt(0));
  const row = clamp(Math.floor((90 - latitude) / (180 / LAND.height)), 0, LAND.height - 1);
  const column = clamp(Math.floor(wrap(longitude + 180) / (360 / LAND.width)), 0, LAND.width - 1);
  const index = row * LAND.width + column;
  return Boolean((landBits[index >> 3] >> (7 - (index & 7))) & 1);
}

export function globePoint(x, y, center) {
  const rho = Math.hypot(x, y);
  if (rho > 1) {
    return null;
  }
  const c = Math.asin(rho) / RAD;
  const latitude = rho === 0 ? center.latitude : asin(cos(c) * sin(center.latitude) + (y * sin(c) * cos(center.latitude)) / rho);
  const longitude = signed(center.longitude + atan2(x * sin(c), rho * cos(c) * cos(center.latitude) - y * sin(c) * sin(center.latitude)));
  return {latitude, longitude};
}

export function daylight(point, light) {
  return sin(point.latitude) * sin(light.latitude) + cos(point.latitude) * cos(light.latitude) * cos(point.longitude - light.longitude);
}

function rotation(yaw, pitch) {
  const [cy, sy, cp, sp] = [cos(yaw), sin(yaw), cos(pitch), sin(pitch)];
  return [cy, 0, sy, sp * sy, cp, -sp * cy, -cp * sy, sp, cp * cy];
}

export function lens(view, width, height) {
  const ky = view.square ? height / view.fov : ((REACH * view.anchor * height) / 90) * (180 / view.fov);
  return {matrix: rotation(-view.azimuth, -view.altitude), kx: view.square ? ky : width / view.fov, ky, cx: width / 2, cy: view.anchor * height, width, height, view};
}

export function place(sight, alt, az) {
  const flat = cos(alt);
  const [m0, m1, m2, m3, m4, m5, m6, m7, m8] = sight.matrix;
  const point = {x: sin(az) * flat, y: -sin(alt), z: cos(az) * flat};
  const turned = {x: m0 * point.x + m1 * point.y + m2 * point.z, y: m3 * point.x + m4 * point.y + m5 * point.z, z: m6 * point.x + m7 * point.y + m8 * point.z};
  const lon = atan2(turned.x, turned.z);
  const lat = asin(-turned.y);
  return {x: sight.cx + sight.kx * lon, y: sight.cy - sight.ky * lat, lon, lat};
}

function horizon(sight, steps) {
  return Array.from({length: steps + 1}, (_, index) => place(sight, 0, sight.view.azimuth - 180 + (360 * index) / steps)).sort((a, b) => a.x - b.x);
}

function storedPlace() {
  try {
    const value = JSON.parse(localStorage.getItem(PLACE_KEY));
    return value && finite(value.latitude) && finite(value.longitude) && Math.abs(value.latitude) <= 90 && Math.abs(value.longitude) <= 180 ? value : null;
  } catch {
    return null;
  }
}

function keepPlace(value) {
  try {
    if (value) {
      localStorage.setItem(PLACE_KEY, JSON.stringify(value));
    } else {
      localStorage.removeItem(PLACE_KEY);
    }
  } catch {
    return;
  }
}

function element(tag, attributes = {}, ...children) {
  const node = tag === "svg" || tag === "path" ? document.createElementNS("http://www.w3.org/2000/svg", tag) : document.createElement(tag);
  for (const [name, value] of Object.entries(attributes)) {
    node.setAttribute(name, value);
  }
  node.append(...children);
  return node;
}

function icon(name) {
  return element("svg", {viewBox: "0 0 16 16", "aria-hidden": "true", focusable: "false"}, ...ICONS[name].map((d) => element("path", {d})));
}

function sheet(text) {
  const styles = new CSSStyleSheet();
  styles.replaceSync(text);
  return styles;
}

function registerProps() {
  if (!globalThis.CSS || !CSS.registerProperty) {
    return;
  }
  for (const name of PROPS.slice(0, 3)) {
    try {
      CSS.registerProperty({name, syntax: "<color>", inherits: true, initialValue: "black"});
    } catch (error) {
      if (error.name !== "InvalidModificationError") {
        throw error;
      }
    }
  }
}

function emit(name, detail) {
  document.dispatchEvent(new CustomEvent(`cosmos:${name}`, {detail}));
}

let cosmosSheet = null;

function rootSheet() {
  cosmosSheet ??= new CSSStyleSheet();
  if (!document.adoptedStyleSheets.includes(cosmosSheet)) {
    document.adoptedStyleSheets = [...document.adoptedStyleSheets, cosmosSheet];
  }
  return cosmosSheet;
}

function sensorsGranted() {
  if (typeof DeviceOrientationEvent.requestPermission !== "function") {
    return Promise.resolve(true);
  }
  const names = "ondeviceorientationabsolute" in window ? ["accelerometer", "gyroscope", "magnetometer"] : ["accelerometer", "gyroscope"];
  return Promise.resolve()
    .then(() => Promise.all(names.map((name) => navigator.permissions.query({name}))))
    .then((statuses) => statuses.every((status) => status.state === "granted"), () => false);
}

export function transparent(color) {
  return /^transparent$|^rgba\(.*,\s*0\)$|\/\s*0\)$/.test(color);
}

function surfacesCleared() {
  return [document.documentElement, document.body].every((node) => {
    const style = getComputedStyle(node);
    return style.backgroundImage === "none" && transparent(style.backgroundColor);
  });
}

const SKY_CSS = `
:host { position: fixed; inset: 0; z-index: -1; display: block; pointer-events: none; contain: strict; }
canvas { display: block; width: 100%; height: 100%; }
:host([data-mode="colors"]) canvas, :host([data-mode="off"]) canvas, :host([data-covered]) canvas { display: none; }
:host([data-scheme="light"]) { --base: #ffffff; }
:host([data-scheme="dark"]) { --base: #000000; }
.panel { pointer-events: auto; position: fixed; inset: 1rem 1rem auto auto; margin: 0; width: min(22rem, calc(100vw - 2rem)); box-sizing: border-box;
  padding: 0.9rem; border: 1px solid color-mix(in srgb, var(--cosmos-text, CanvasText) 22%, transparent); border-radius: 1rem;
  color: var(--cosmos-text, CanvasText); background: color-mix(in srgb, var(--cosmos-sky-top, Canvas) 20%, var(--base, Canvas));
  backdrop-filter: blur(14px) saturate(1.2); box-shadow: 0 18px 48px rgb(0 0 0 / 35%); font: 14px/1.4 system-ui, sans-serif; }
.panel::backdrop { background: transparent; }
header { display: flex; align-items: center; gap: 0.6rem; margin-bottom: 0.6rem; }
header strong { font-size: 1rem; }
header .close { margin-inline-start: auto; }
.note { margin: 0 0 0.7rem; font-size: 0.85rem; opacity: 0.85; }
.row { display: flex; gap: 0.4rem; margin-bottom: 0.5rem; }
button { display: inline-grid; place-items: center; inline-size: 2.4rem; block-size: 2.4rem; padding: 0; border-radius: 0.7rem; cursor: pointer;
  color: inherit; background: color-mix(in srgb, currentColor 8%, transparent); border: 1px solid color-mix(in srgb, currentColor 25%, transparent); }
button[aria-pressed="true"] { background: color-mix(in srgb, currentColor 22%, transparent); border-color: currentColor; }
button:focus-visible { outline: 2px solid currentColor; outline-offset: 2px; }
button[hidden] { display: none; }
svg { inline-size: 1.15rem; block-size: 1.15rem; fill: none; stroke: currentColor; stroke-width: 1.4; stroke-linecap: round; stroke-linejoin: round; }
.hint { margin: 0.3rem 0 0; font-size: 0.78rem; opacity: 0.75; }
@media (prefers-reduced-transparency: reduce) { .panel { backdrop-filter: none; background: var(--base, Canvas); } }
`;

const GLOBE_CSS = `
:host { display: inline-block; inline-size: var(--size); block-size: var(--size); border-radius: 50%; cursor: pointer; }
:host(:focus-visible) { outline: 2px solid currentColor; outline-offset: 2px; }
canvas { display: block; inline-size: 100%; block-size: 100%; }
`;

const Base = globalThis.HTMLElement ?? class {};

export class CosmosSky extends Base {
  static observedAttributes = ["latitude", "longitude", "time", "mode", "hotkey", "cookie-domain"];
  fallback = null;
  #root;
  #canvas;
  #panel;
  #note;
  #hint;
  #buttons = {};
  #timer = 0;
  #frame = 0;
  #paints = 0;
  #gps = null;
  #view = null;
  #following = false;
  #opener = null;
  #lastStage = "";
  #noteText = "";

  constructor() {
    super();
    this.#root = this.attachShadow({mode: "open"});
    this.#root.adoptedStyleSheets = [sheet(SKY_CSS)];
    this.#canvas = element("canvas", {"aria-hidden": "true"});
    this.#root.append(this.#canvas);
  }

  get paints() {
    return this.#paints;
  }

  get hotkey() {
    return this.getAttribute("hotkey") || HOTKEY;
  }

  get framed() {
    return window.top !== window;
  }

  get mode() {
    const wanted = readPrefs(document.cookie).mode || (MODES.includes(this.getAttribute("mode")) ? this.getAttribute("mode") : "full");
    return this.framed && wanted === "full" ? "colors" : wanted;
  }

  get settings() {
    return {mode: this.mode, orientation: this.#following ? "on" : "off", place: this.#placeNow().source, open: this.#isOpen()};
  }

  set settings(value) {
    const next = {...readPrefs(document.cookie)};
    if (MODES.includes(value?.mode)) {
      next.mode = value.mode;
    }
    if (SWITCHES.includes(value?.orientation)) {
      next.orientation = value.orientation;
    }
    document.cookie = prefsCookie(next, this.getAttribute("cookie-domain"), location.protocol === "https:");
    const synced = this.#syncOrientation();
    this.refresh();
    synced.then(() => emit("change", this.settings));
  }

  connectedCallback() {
    registerProps();
    this.#gps = storedPlace();
    document.addEventListener("visibilitychange", this.#onVisibility);
    window.addEventListener("resize", this.#onResize);
    this.#syncOrientation();
    this.refresh();
    this.#askPermissionlessGps();
  }

  disconnectedCallback() {
    window.clearTimeout(this.#timer);
    window.cancelAnimationFrame(this.#frame);
    document.removeEventListener("visibilitychange", this.#onVisibility);
    window.removeEventListener("resize", this.#onResize);
    this.#follow(false);
  }

  attributeChangedCallback() {
    if (this.isConnected) {
      this.refresh();
    }
  }

  open() {
    if (!this.#panel) {
      this.#root.append(this.#buildPanel());
    }
    this.#syncPanel();
    if (!this.#isOpen()) {
      this.#opener = document.activeElement;
      this.#panel.showPopover();
    }
  }

  close() {
    if (this.#isOpen()) {
      this.#panel.hidePopover();
    }
  }

  toggle() {
    if (this.#isOpen()) {
      this.close();
    } else {
      this.open();
    }
  }

  refresh() {
    window.clearTimeout(this.#timer);
    const mode = this.mode;
    this.dataset.mode = mode;
    const root = document.documentElement;
    root.setAttribute("data-cosmos-mode", mode);
    if (mode === "off") {
      rootSheet().replaceSync("");
      MARKS.forEach((name) => root.removeAttribute(name));
      this.#noteText = "Cosmos is off.";
      this.#syncPanel();
      return;
    }
    const ms = this.#now();
    const where = this.#placeNow();
    const look = tones(ms, where.latitude, where.longitude);
    rootSheet().replaceSync(`:root { --cosmos-sky-top: ${css(look.top)}; --cosmos-sky-bottom: ${css(look.bottom)}; --cosmos-text: ${css(look.text)}; --cosmos-scheme: ${look.scheme}; --cosmos-stage: ${look.stage}; --cosmos-sun-altitude: ${look.altitude.toFixed(2)}; }`);
    root.setAttribute("data-cosmos-stage", look.stage);
    root.setAttribute("data-cosmos-scheme", look.scheme);
    root.setAttribute("data-cosmos-legible", look.legible);
    this.dataset.scheme = look.scheme;
    const covered = mode === "full" && !surfacesCleared();
    this.toggleAttribute("data-covered", covered);
    this.#noteText = `${STAGE_LABELS[look.stage]} · ${Math.abs(where.latitude).toFixed(1)}° ${where.latitude >= 0 ? "N" : "S"} ${Math.abs(where.longitude).toFixed(1)}° ${where.longitude >= 0 ? "E" : "W"} · ${SOURCE_LABELS[where.source]}${covered ? " · this page keeps its own background" : ""}`;
    this.#syncPanel();
    if (mode === "full" && !covered && document.visibilityState !== "hidden") {
      this.#draw(ms, where, look);
    }
    if (look.stage !== this.#lastStage) {
      this.#lastStage = look.stage;
      emit("change", this.settings);
    }
    if (!this.hasAttribute("time") && document.visibilityState !== "hidden") {
      this.#timer = window.setTimeout(() => this.refresh(), MINUTE - (Date.now() % MINUTE) + 50);
    }
  }

  #now() {
    const fixed = Date.parse(this.getAttribute("time") || "");
    return Number.isFinite(fixed) ? fixed : Date.now();
  }

  #placeNow() {
    if (finite(this.getAttribute("latitude")) && finite(this.getAttribute("longitude"))) {
      return {latitude: Number(this.getAttribute("latitude")), longitude: Number(this.getAttribute("longitude")), source: "attribute"};
    }
    if (this.#gps) {
      return {...this.#gps, source: "gps"};
    }
    return zonePlace(Intl.DateTimeFormat().resolvedOptions().timeZone, this.fallback);
  }

  #isOpen() {
    return Boolean(this.#panel?.matches(":popover-open"));
  }

  #buildPanel() {
    const button = (name, label, run) => {
      const node = element("button", {type: "button", title: label, "aria-label": label}, icon(name));
      node.addEventListener("click", run);
      this.#buttons[name] = node;
      return node;
    };
    this.#note = element("p", {class: "note", "aria-live": "polite"});
    this.#hint = element("p", {class: "hint"});
    this.#panel = element("div", {class: "panel", popover: "auto", role: "dialog", "aria-label": "Cosmos settings"},
      element("header", {}, element("cosmos-globe", {size: "28", tabindex: "-1"}), element("strong", {}, "Cosmos"),
        button("close", "Close the cosmos settings (Esc)", () => this.close())),
      this.#note,
      element("div", {class: "row", role: "group", "aria-label": "Mode"},
        button("full", "Show the full sky", () => (this.settings = {mode: "full"})),
        button("colors", "Show the sky colors only", () => (this.settings = {mode: "colors"})),
        button("off", "Switch the cosmos off", () => (this.settings = {mode: "off"}))),
      element("div", {class: "row", role: "group", "aria-label": "Place and view"},
        button("orientation", "Follow the phone: the sky turns with it", () => this.#toggleOrientation()),
        button("locate", "Use the precise location of this device", () => this.#locate()),
        button("forget", "Forget the precise location and use the timezone", () => this.#forget())),
      this.#hint);
    this.#panel.addEventListener("toggle", (event) => {
      if (event.newState === "open") {
        this.#buttons[this.mode]?.focus();
        emit("open", this.settings);
        return;
      }
      if (this.#opener instanceof HTMLElement && this.#opener.isConnected) {
        this.#opener.focus();
      }
      this.#opener = null;
      emit("close", this.settings);
    });
    return this.#panel;
  }

  #syncPanel() {
    if (!this.#panel) {
      return;
    }
    const mode = this.mode;
    for (const name of MODES) {
      this.#buttons[name].setAttribute("aria-pressed", String(name === mode));
    }
    this.#buttons.orientation.hidden = !this.#canFollow();
    this.#buttons.orientation.setAttribute("aria-pressed", String(this.#following));
    this.#buttons.forget.hidden = !this.#gps;
    this.#note.textContent = this.#noteText;
    this.#hint.textContent = `${keysLabel(this.hotkey)} opens and closes this panel.`;
  }

  #canFollow() {
    return "DeviceOrientationEvent" in window && matchMedia("(pointer: coarse)").matches && !this.framed;
  }

  #still() {
    return matchMedia("(prefers-reduced-motion: reduce)").matches;
  }

  #syncOrientation() {
    const wanted = readPrefs(document.cookie).orientation;
    const able = this.#canFollow() && !this.#still() && this.mode === "full" && wanted !== "off";
    const allowed = able && wanted !== "on" ? sensorsGranted() : Promise.resolve(able);
    return allowed.then((on) => this.#follow(on && this.isConnected));
  }

  async #toggleOrientation() {
    if (!this.#following && typeof DeviceOrientationEvent !== "undefined" && typeof DeviceOrientationEvent.requestPermission === "function") {
      const state = await DeviceOrientationEvent.requestPermission().catch(() => "denied");
      if (state !== "granted") {
        return;
      }
    }
    this.settings = {orientation: this.#following ? "off" : "on"};
  }

  #follow(on) {
    const name = "ondeviceorientationabsolute" in window ? "deviceorientationabsolute" : "deviceorientation";
    window.removeEventListener(name, this.#onTurn);
    this.#following = on;
    this.#view = null;
    if (on) {
      window.addEventListener(name, this.#onTurn);
    }
  }

  #onTurn = (event) => {
    if (event.alpha === null || event.beta === null || event.gamma === null) {
      return;
    }
    const next = pose(event.alpha, event.beta, event.gamma, event.webkitCompassHeading);
    this.#view = this.#view ? {azimuth: wrap(this.#view.azimuth + signed(next.azimuth - this.#view.azimuth) * 0.25), altitude: this.#view.altitude + (next.altitude - this.#view.altitude) * 0.25} : next;
    if (!this.#frame && this.mode === "full") {
      this.#frame = window.requestAnimationFrame(() => {
        this.#frame = 0;
        this.#repaint();
      });
    }
  };

  #onVisibility = () => this.refresh();

  #onResize = () => {
    if (!this.#frame && this.mode === "full") {
      this.#frame = window.requestAnimationFrame(() => {
        this.#frame = 0;
        this.#repaint();
      });
    }
  };

  #repaint() {
    if (this.hasAttribute("data-covered")) {
      return;
    }
    const where = this.#placeNow();
    const ms = this.#now();
    this.#draw(ms, where, tones(ms, where.latitude, where.longitude));
  }

  async #askPermissionlessGps() {
    if (this.#gps || !navigator.permissions || !navigator.geolocation) {
      return;
    }
    const state = await navigator.permissions.query({name: "geolocation"}).then((status) => status.state, () => "unknown");
    if (state === "granted") {
      this.#locate();
    }
  }

  #locate() {
    navigator.geolocation?.getCurrentPosition((position) => {
      this.#gps = {latitude: Math.round(position.coords.latitude * 100) / 100, longitude: Math.round(position.coords.longitude * 100) / 100};
      keepPlace(this.#gps);
      this.refresh();
      emit("change", this.settings);
    }, () => null, {maximumAge: 3600000, timeout: 15000});
  }

  #forget() {
    this.#gps = null;
    keepPlace(null);
    this.refresh();
    emit("change", this.settings);
  }

  #draw(ms, where, look) {
    const canvas = this.#canvas;
    const paint = canvas.getContext("2d");
    if (!paint) {
      return;
    }
    const width = window.innerWidth;
    const height = window.innerHeight;
    if (canvas.width !== width || canvas.height !== height) {
      canvas.width = width;
      canvas.height = height;
    }
    this.#paints += 1;
    const following = this.#following && this.#view;
    const view = following ? {...PHONE, ...this.#view} : {...DESK, azimuth: where.latitude >= 0 ? 180 : 0};
    const sight = lens(view, width, height);
    const at = (alt, az) => place(sight, alt, az);
    const inside = (spot, margin) => spot.x >= -margin && spot.x <= width + margin && spot.y >= -margin && spot.y <= height + margin;
    const reach = view.square ? (width / sight.kx) / 2 + 10 : view.fov / 2 + 10;
    const light = sun(ms, where.latitude, where.longitude);
    const night = moon(ms, where.latitude, where.longitude);
    const low = at(0, view.azimuth);
    const high = at(90, view.azimuth);
    const air = paint.createLinearGradient(low.x + (high.x - low.x) / REACH, low.y + (high.y - low.y) / REACH, low.x, low.y);
    air.addColorStop(0, css(look.top));
    air.addColorStop(1, css(look.bottom));
    paint.fillStyle = air;
    paint.fillRect(0, 0, width, height);
    const dusk = Math.max(0, 1 - Math.abs(light.alt) / 14);
    const glowAt = at(Math.max(light.alt, -3), light.az);
    if (dusk > 0 && Math.abs(glowAt.lon) <= 135) {
      const x = clamp(glowAt.x, sight.cx - sight.kx * 100, sight.cx + sight.kx * 100);
      const glow = paint.createRadialGradient(x, glowAt.y, 0, x, glowAt.y, width * 0.5);
      glow.addColorStop(0, `rgb(255 186 128 / ${(0.45 * dusk).toFixed(3)})`);
      glow.addColorStop(1, "rgb(255 186 128 / 0)");
      paint.fillStyle = glow;
      paint.fillRect(0, 0, width, height);
    }
    const shine = starlight(light.alt);
    if (shine > 0) {
      paint.fillStyle = "#ffffff";
      for (const entry of DATA.stars) {
        const spot = star(entry, ms, where.latitude, where.longitude);
        if (spot.alt <= 0.5) {
          continue;
        }
        const point = at(spot.alt, spot.az);
        if (Math.abs(point.lon) <= reach && inside(point, 4)) {
          paint.globalAlpha = shine * clamp(1.15 - spot.mag * 0.17, 0.25, 1);
          paint.beginPath();
          paint.arc(point.x, point.y, clamp(1.9 - 0.32 * spot.mag, 0.45, 2.6), 0, Math.PI * 2);
          paint.fill();
        }
      }
      paint.globalAlpha = 1;
    }
    const sunAt = at(light.alt, light.az);
    if (light.alt > -2 && Math.abs(sunAt.lon) <= reach && inside(sunAt, 100)) {
      const halo = paint.createRadialGradient(sunAt.x, sunAt.y, 0, sunAt.x, sunAt.y, 90);
      halo.addColorStop(0, "rgb(255 236 200 / 0.55)");
      halo.addColorStop(1, "rgb(255 236 200 / 0)");
      paint.fillStyle = halo;
      paint.fillRect(sunAt.x - 90, sunAt.y - 90, 180, 180);
      paint.fillStyle = css(mix([255, 170, 90], [255, 246, 220], clamp(light.alt / 20, 0, 1)));
      paint.beginPath();
      paint.arc(sunAt.x, sunAt.y, 15, 0, Math.PI * 2);
      paint.fill();
    }
    const moonAt = at(night.alt, night.az);
    if (night.alt > -2 && Math.abs(moonAt.lon) <= reach && inside(moonAt, 100)) {
      drawMoon(paint, moonAt, 12, night);
    }
    const edge = horizon(sight, 96);
    const bottom = Math.max(height, ...edge.map((spot) => spot.y)) + 2;
    const ground = paint.createLinearGradient(0, low.y, 0, low.y + Math.max(height - sight.cy, 1));
    ground.addColorStop(0, css(mix(look.bottom, [4, 6, 10], 0.72)));
    ground.addColorStop(1, css(mix(look.bottom, [4, 6, 10], 0.9)));
    paint.fillStyle = ground;
    paint.beginPath();
    edge.forEach((spot, index) => (index ? paint.lineTo(spot.x, spot.y) : paint.moveTo(spot.x, spot.y)));
    paint.lineTo(edge[edge.length - 1].x, bottom);
    paint.lineTo(edge[0].x, bottom);
    paint.closePath();
    paint.fill();
    if (following) {
      paint.fillStyle = "rgb(255 255 255 / 0.6)";
      paint.font = "600 12px system-ui, sans-serif";
      paint.textAlign = "center";
      COMPASS.forEach((label, index) => {
        const spot = at(0, index * 45);
        if (Math.abs(spot.lon) <= reach && inside(spot, 0)) {
          paint.fillText(label, spot.x, spot.y + 16);
        }
      });
    }
  }
}

function drawMoon(paint, at, radius, body) {
  const tilt = body.tilt * RAD;
  paint.save();
  paint.translate(at.x, at.y);
  paint.rotate(Math.atan2(-Math.cos(tilt), -Math.sin(tilt)));
  const halo = paint.createRadialGradient(0, 0, radius, 0, 0, radius * 4);
  halo.addColorStop(0, `rgb(235 240 255 / ${(0.28 * body.lit).toFixed(3)})`);
  halo.addColorStop(1, "rgb(235 240 255 / 0)");
  paint.fillStyle = halo;
  paint.fillRect(-radius * 4, -radius * 4, radius * 8, radius * 8);
  paint.fillStyle = "rgb(60 68 92 / 0.55)";
  paint.beginPath();
  paint.arc(0, 0, radius, 0, Math.PI * 2);
  paint.fill();
  paint.fillStyle = "#f3f0e4";
  paint.beginPath();
  paint.arc(0, 0, radius, -Math.PI / 2, Math.PI / 2, false);
  paint.ellipse(0, 0, Math.abs(2 * body.lit - 1) * radius, radius, 0, Math.PI / 2, -Math.PI / 2, body.lit < 0.5);
  paint.closePath();
  paint.fill();
  paint.restore();
}

export class CosmosGlobe extends Base {
  static observedAttributes = ["size", "time"];
  #canvas;
  #timer = 0;

  constructor() {
    super();
    const root = this.attachShadow({mode: "open"});
    root.adoptedStyleSheets = [sheet(GLOBE_CSS)];
    this.#canvas = element("canvas", {"aria-hidden": "true"});
    root.append(this.#canvas);
    this.addEventListener("click", () => globalThis.cosmos?.open());
    this.addEventListener("keydown", (event) => {
      if (event.key === "Enter" || event.key === " ") {
        event.preventDefault();
        globalThis.cosmos?.open();
      }
    });
  }

  connectedCallback() {
    if (!this.hasAttribute("role")) {
      this.setAttribute("role", "button");
    }
    if (!this.hasAttribute("tabindex")) {
      this.setAttribute("tabindex", "0");
    }
    const label = `Cosmos settings (${keysLabel(skyElement()?.hotkey ?? HOTKEY)})`;
    this.setAttribute("title", label);
    this.setAttribute("aria-label", label);
    this.draw();
  }

  disconnectedCallback() {
    window.clearTimeout(this.#timer);
  }

  attributeChangedCallback() {
    if (this.isConnected) {
      this.draw();
    }
  }

  get size() {
    const wanted = Number(this.getAttribute("size"));
    return clamp(Number.isFinite(wanted) && wanted > 0 ? Math.round(wanted) : GLOBE.size, 8, GLOBE.max);
  }

  draw() {
    window.clearTimeout(this.#timer);
    const size = this.size;
    const scale = Math.min(window.devicePixelRatio || 1, 2);
    const pixels = Math.round(size * scale);
    this.style.setProperty("--size", `${size}px`);
    const canvas = this.#canvas;
    canvas.width = pixels;
    canvas.height = pixels;
    const paint = canvas.getContext("2d");
    if (!paint || !DATA.land) {
      return;
    }
    const fixed = Date.parse(this.getAttribute("time") || "");
    const ms = Number.isFinite(fixed) ? fixed : Date.now();
    const light = subsolar(ms);
    const center = {latitude: GLOBE.tilt, longitude: signed(light.longitude + GLOBE.lead)};
    const image = paint.createImageData(pixels, pixels);
    for (let y = 0; y < pixels; y += 1) {
      for (let x = 0; x < pixels; x += 1) {
        const point = globePoint(((x + 0.5) / pixels) * 2 - 1, 1 - ((y + 0.5) / pixels) * 2, center);
        if (!point) {
          continue;
        }
        const day = clamp((daylight(point, light) + 0.1) / 0.2, 0, 1);
        const land = landAt(point.latitude, point.longitude);
        const color = mix(land ? [24, 34, 30] : [8, 16, 34], land ? [96, 140, 84] : [38, 98, 168], day);
        const offset = (y * pixels + x) * 4;
        image.data.set([...color.map(Math.round), 255], offset);
      }
    }
    paint.putImageData(image, 0, 0);
    paint.strokeStyle = "rgb(150 190 255 / 0.55)";
    paint.lineWidth = Math.max(1, scale);
    paint.beginPath();
    paint.arc(pixels / 2, pixels / 2, pixels / 2 - paint.lineWidth / 2, 0, Math.PI * 2);
    paint.stroke();
    if (!this.hasAttribute("time")) {
      this.#timer = window.setTimeout(() => this.draw(), MINUTE - (Date.now() % MINUTE) + 50);
    }
  }
}

function skyElement() {
  return document.querySelector("cosmos-sky");
}

function mount() {
  const script = document.querySelector("script[data-cosmos]");
  if (!script) {
    return;
  }
  const config = JSON.parse(script.dataset.cosmos || "{}");
  const attach = () => {
    if (!document.body || document.querySelector("cosmos-sky")) {
      return;
    }
    const sky = document.createElement("cosmos-sky");
    sky.fallback = home(config);
    if (config.cookieDomain) {
      sky.setAttribute("cookie-domain", config.cookieDomain);
    }
    if (config.hotkey) {
      sky.setAttribute("hotkey", config.hotkey);
    }
    document.body.prepend(sky);
  };
  const bodyWatch = new MutationObserver(attach);
  let watched = null;
  const follow = () => {
    if (document.body !== watched) {
      bodyWatch.disconnect();
      watched = document.body;
      if (watched) {
        bodyWatch.observe(watched, {childList: true});
      }
    }
    attach();
  };
  new MutationObserver(follow).observe(document.documentElement, {childList: true});
  follow();
}

function wire() {
  globalThis.cosmos = {
    open: () => skyElement()?.open(),
    close: () => skyElement()?.close(),
    toggle: () => skyElement()?.toggle(),
    refresh: () => skyElement()?.refresh(),
    get settings() {
      return skyElement()?.settings ?? null;
    },
    set settings(value) {
      const sky = skyElement();
      if (sky) {
        sky.settings = value;
      }
    },
  };
  document.addEventListener("keydown", (event) => {
    const sky = skyElement();
    if (!sky || event.repeat || !pressed(parseHotkey(sky.hotkey), event) || typing(event.composedPath()[0])) {
      return;
    }
    event.preventDefault();
    sky.toggle();
  });
  document.addEventListener("click", (event) => {
    if (event.composedPath().some((node) => node instanceof Element && node.hasAttribute("data-cosmos-open"))) {
      event.preventDefault();
      globalThis.cosmos.open();
    }
  });
  const byHash = () => {
    if (location.hash === "#cosmos") {
      globalThis.cosmos.open();
    }
  };
  window.addEventListener("hashchange", byHash);
  customElements.define("cosmos-globe", CosmosGlobe);
  customElements.define("cosmos-sky", CosmosSky);
  mount();
  byHash();
}

if (globalThis.customElements && !customElements.get("cosmos-sky")) {
  wire();
}
